package main

import (
	"flag"
	"log"
	"net/http"
	"os"
	"time"
)

func main() {
	healthcheck := flag.Bool("healthcheck", false, "probe /healthz on the local server and exit")
	flag.Parse()
	port := os.Getenv("PORT")
	if port == "" {
		port = "8000"
	}
	if *healthcheck {
		os.Exit(probe("http://127.0.0.1:" + port + "/healthz"))
	}
	server := &http.Server{Addr: ":" + port, Handler: newServer(), ReadHeaderTimeout: 10 * time.Second}
	log.Printf("listening on :%s", port)
	log.Fatal(server.ListenAndServe())
}

// probe is the container health check: exit status 0 when /healthz answers 200.
func probe(url string) int {
	client := http.Client{Timeout: 2 * time.Second}
	response, err := client.Get(url)
	if err != nil {
		return 1
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		return 1
	}
	return 0
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strconv"
)

const maxBodyBytes = 1 << 20

type resource struct {
	label      string
	fields     []FieldSpec
	store      *Store
	references []reference
}

// reference is a many-to-one link: key holds the id of an item in the parent's store.
type reference struct {
	key   string
	label string
	store *Store
}

// newResource builds one entity's handlers; deleting a parent deletes what references it.
func newResource(label string, fields []FieldSpec, references ...reference) *resource {
	res := &resource{label: label, fields: fields, store: NewStore(), references: references}
	for _, ref := range references {
		ref.store.CascadeTo(ref.key, res.store)
	}
	return res
}

// newServer wires every route: CRUD for each entity, plus GET /healthz.
func newServer() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})

	members := newResource("Member", memberFields)
	mux.HandleFunc("GET /members", members.list)
	mux.HandleFunc("POST /members", members.create)
	mux.HandleFunc("GET /members/{id}", members.get)
	mux.HandleFunc("PATCH /members/{id}", members.update)
	mux.HandleFunc("DELETE /members/{id}", members.delete)

	books := newResource("Book", bookFields)
	mux.HandleFunc("GET /books", books.list)
	mux.HandleFunc("POST /books", books.create)
	mux.HandleFunc("GET /books/{id}", books.get)
	mux.HandleFunc("PATCH /books/{id}", books.update)
	mux.HandleFunc("DELETE /books/{id}", books.delete)

	librarians := newResource("Librarian", librarianFields)
	mux.HandleFunc("GET /librarians", librarians.list)
	mux.HandleFunc("POST /librarians", librarians.create)
	mux.HandleFunc("GET /librarians/{id}", librarians.get)
	mux.HandleFunc("PATCH /librarians/{id}", librarians.update)
	mux.HandleFunc("DELETE /librarians/{id}", librarians.delete)

	loans := newResource("Loan", loanFields, reference{key: "member_id", label: "Member", store: members.store}, reference{key: "book_id", label: "Book", store: books.store})
	mux.HandleFunc("GET /loans", loans.list)
	mux.HandleFunc("POST /loans", loans.create)
	mux.HandleFunc("GET /loans/{id}", loans.get)
	mux.HandleFunc("PATCH /loans/{id}", loans.update)
	mux.HandleFunc("DELETE /loans/{id}", loans.delete)
	return mux
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func detail(w http.ResponseWriter, status int, message any) {
	writeJSON(w, status, map[string]any{"detail": message})
}

func readBody(w http.ResponseWriter, r *http.Request) (map[string]any, bool) {
	var body map[string]any
	err := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBodyBytes)).Decode(&body)
	var tooLarge *http.MaxBytesError
	switch {
	case errors.As(err, &tooLarge):
		detail(w, http.StatusRequestEntityTooLarge, "Body too large")
		return nil, false
	case err != nil || body == nil:
		detail(w, http.StatusUnprocessableEntity, "Body must be a JSON object")
		return nil, false
	}
	return body, true
}

func intParam(r *http.Request, name string, fallback int) (int, bool) {
	raw := r.URL.Query().Get(name)
	if raw == "" {
		return fallback, true
	}
	value, err := strconv.Atoi(raw)
	return value, err == nil
}

func (res *resource) id(w http.ResponseWriter, r *http.Request) (int64, bool) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil || id < 1 {
		detail(w, http.StatusNotFound, res.label+" not found")
		return 0, false
	}
	return id, true
}

func (res *resource) list(w http.ResponseWriter, r *http.Request) {
	limit, okLimit := intParam(r, "limit", 50)
	offset, okOffset := intParam(r, "offset", 0)
	if !okLimit || !okOffset || limit < 1 || limit > 200 || offset < 0 {
		detail(w, http.StatusUnprocessableEntity, []string{"limit or offset out of range"})
		return
	}
	where := make(map[string]int64, len(res.references))
	for _, ref := range res.references {
		raw := r.URL.Query().Get(ref.key)
		if raw == "" {
			continue
		}
		id, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || id < 1 {
			detail(w, http.StatusUnprocessableEntity, []string{ref.key + ": expected a positive integer"})
			return
		}
		where[ref.key] = id
	}
	writeJSON(w, http.StatusOK, res.store.List(limit, offset, where))
}

// missingParent names the first referenced parent that does not exist.
func (res *resource) missingParent(data map[string]any) (string, bool) {
	for _, ref := range res.references {
		number, ok := data[ref.key].(float64)
		if !ok {
			continue
		}
		if _, found := ref.store.Get(int64(number)); !found {
			return fmt.Sprintf("%s %d not found", ref.label, int64(number)), true
		}
	}
	return "", false
}

func (res *resource) create(w http.ResponseWriter, r *http.Request) {
	body, ok := readBody(w, r)
	if !ok {
		return
	}
	data, problems := validate(res.fields, body, false)
	if len(problems) > 0 {
		detail(w, http.StatusUnprocessableEntity, problems)
		return
	}
	if message, missing := res.missingParent(data); missing {
		detail(w, http.StatusUnprocessableEntity, message)
		return
	}
	writeJSON(w, http.StatusCreated, res.store.Create(data))
}

func (res *resource) get(w http.ResponseWriter, r *http.Request) {
	id, ok := res.id(w, r)
	if !ok {
		return
	}
	item, found := res.store.Get(id)
	if !found {
		detail(w, http.StatusNotFound, res.label+" not found")
		return
	}
	writeJSON(w, http.StatusOK, item)
}

func (res *resource) update(w http.ResponseWriter, r *http.Request) {
	id, ok := res.id(w, r)
	if !ok {
		return
	}
	body, ok := readBody(w, r)
	if !ok {
		return
	}
	data, problems := validate(res.fields, body, true)
	if len(problems) > 0 {
		detail(w, http.StatusUnprocessableEntity, problems)
		return
	}
	if _, found := res.store.Get(id); !found {
		detail(w, http.StatusNotFound, res.label+" not found")
		return
	}
	if message, missing := res.missingParent(data); missing {
		detail(w, http.StatusUnprocessableEntity, message)
		return
	}
	item, found := res.store.Update(id, data)
	if !found {
		detail(w, http.StatusNotFound, res.label+" not found")
		return
	}
	writeJSON(w, http.StatusOK, item)
}

func (res *resource) delete(w http.ResponseWriter, r *http.Request) {
	id, ok := res.id(w, r)
	if !ok {
		return
	}
	if !res.store.Delete(id) {
		detail(w, http.StatusNotFound, res.label+" not found")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

