package main

import (
	"fmt"
	"math"
	"sort"
	"time"
)

// FieldType is the JSON type a field accepts.
type FieldType string

// The field types an entity can use.
const (
	TypeString   FieldType = "string"
	TypeText     FieldType = "text"
	TypeInteger  FieldType = "integer"
	TypeFloat    FieldType = "float"
	TypeBoolean  FieldType = "boolean"
	TypeDate     FieldType = "date"
	TypeDateTime FieldType = "datetime"
)

// FieldSpec describes one field of an entity.
type FieldSpec struct {
	Name     string
	Type     FieldType
	Required bool
}

func accepts(kind FieldType, value any) bool {
	switch kind {
	case TypeString:
		text, ok := value.(string)
		return ok && len(text) <= 255
	case TypeText:
		_, ok := value.(string)
		return ok
	case TypeInteger:
		number, ok := value.(float64)
		return ok && number == math.Trunc(number) && math.Abs(number) < 1<<53
	case TypeFloat:
		number, ok := value.(float64)
		return ok && !math.IsInf(number, 0) && !math.IsNaN(number)
	case TypeBoolean:
		_, ok := value.(bool)
		return ok
	case TypeDate:
		text, ok := value.(string)
		if !ok {
			return false
		}
		_, err := time.Parse(time.DateOnly, text)
		return err == nil
	case TypeDateTime:
		text, ok := value.(string)
		if !ok {
			return false
		}
		_, err := time.Parse(time.RFC3339, text)
		return err == nil
	}
	return false
}

// validate checks a decoded JSON object; partial (PATCH) allows any subset of fields.
func validate(fields []FieldSpec, body map[string]any, partial bool) (map[string]any, []string) {
	known := make(map[string]FieldSpec, len(fields))
	for _, field := range fields {
		known[field.Name] = field
	}
	var problems []string
	for key := range body {
		if _, ok := known[key]; !ok {
			problems = append(problems, key+": unknown field")
		}
	}
	data := make(map[string]any, len(fields))
	for _, field := range fields {
		value, present := body[field.Name]
		switch {
		case !present:
			if field.Required && !partial {
				problems = append(problems, field.Name+": required")
			}
		case value == nil && !field.Required:
			data[field.Name] = nil
		case accepts(field.Type, value):
			data[field.Name] = value
		default:
			problems = append(problems, fmt.Sprintf("%s: expected %s", field.Name, field.Type))
		}
	}
	sort.Strings(problems)
	return data, problems
}

package main

import (
	"sort"
	"sync"
	"time"
)

// Item is one stored entity as a JSON object.
type Item map[string]any

// Store keeps one entity's items in memory. Replace it with a database before scaling out.
type Store struct {
	mu         sync.Mutex
	items      map[int64]Item
	next       int64
	dependents []dependent
}

// dependent is a store whose items point at this one's through key.
type dependent struct {
	key   string
	store *Store
}

// NewStore returns an empty store.
func NewStore() *Store {
	return &Store{items: make(map[int64]Item), next: 1}
}

// CascadeTo makes deleting an item here delete the child items whose key holds its id.
func (s *Store) CascadeTo(key string, child *Store) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.dependents = append(s.dependents, dependent{key: key, store: child})
}

// refersTo reports whether a decoded JSON value is the given id.
func refersTo(value any, id int64) bool {
	number, ok := value.(float64)
	return ok && number == float64(id)
}

func matches(item Item, where map[string]int64) bool {
	for key, id := range where {
		if !refersTo(item[key], id) {
			return false
		}
	}
	return true
}

// List returns up to limit items whose where keys match, oldest first, after skipping offset.
func (s *Store) List(limit, offset int, where map[string]int64) []Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := make([]int64, 0, len(s.items))
	for id := range s.items {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	page := make([]Item, 0, limit)
	skipped := 0
	for _, id := range ids {
		item := s.items[id]
		switch {
		case len(page) == limit:
			return page
		case !matches(item, where):
		case skipped < offset:
			skipped++
		default:
			page = append(page, item)
		}
	}
	return page
}

// Get returns the item with the given id.
func (s *Store) Get(id int64) (Item, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	item, ok := s.items[id]
	return item, ok
}

// Create stores a new item and returns it with its id and creation time.
func (s *Store) Create(data map[string]any) Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	item := Item{"id": s.next, "created_at": time.Now().UTC().Format(time.RFC3339)}
	for key, value := range data {
		item[key] = value
	}
	s.items[s.next] = item
	s.next++
	return item
}

// Update merges data into an existing item.
func (s *Store) Update(id int64, data map[string]any) (Item, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	current, ok := s.items[id]
	if !ok {
		return nil, false
	}
	updated := make(Item, len(current))
	for key, value := range current {
		updated[key] = value
	}
	for key, value := range data {
		updated[key] = value
	}
	s.items[id] = updated
	return updated, true
}

// Delete removes an item, and the items that belong to it, and reports whether it existed.
func (s *Store) Delete(id int64) bool {
	s.mu.Lock()
	_, ok := s.items[id]
	delete(s.items, id)
	dependents := s.dependents
	s.mu.Unlock() // not held while the children go: each store locks only itself
	if ok {
		for _, child := range dependents {
			child.store.deleteWhere(child.key, id)
		}
	}
	return ok
}

// deleteWhere deletes every item whose key refers to id (and, in turn, their children).
func (s *Store) deleteWhere(key string, id int64) {
	s.mu.Lock()
	var doomed []int64
	for itemID, item := range s.items {
		if refersTo(item[key], id) {
			doomed = append(doomed, itemID)
		}
	}
	s.mu.Unlock()
	for _, itemID := range doomed {
		s.Delete(itemID)
	}
}

