import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func call(t *testing.T, server *httptest.Server, method, path string, body any) *http.Response {
	t.Helper()
	var payload bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&payload).Encode(body); err != nil {
			t.Fatal(err)
		}
	}
	request, err := http.NewRequest(method, server.URL+path, &payload)
	if err != nil {
		t.Fatal(err)
	}
	request.Header.Set("Content-Type", "application/json")
	response, err := server.Client().Do(request)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { response.Body.Close() })
	return response
}

func expect(t *testing.T, response *http.Response, status int) {
	t.Helper()
	if response.StatusCode != status {
		t.Fatalf("%s %s: status %d, want %d", response.Request.Method, response.Request.URL.Path, response.StatusCode, status)
	}
}

func decode[T any](t *testing.T, response *http.Response, status int) T {
	t.Helper()
	expect(t, response, status)
	var value T
	if err := json.NewDecoder(response.Body).Decode(&value); err != nil {
		t.Fatal(err)
	}
	return value
}

// normalize gives a payload the shape JSON decoding produces (numbers as float64).
func normalize(t *testing.T, value map[string]any) map[string]any {
	t.Helper()
	encoded, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	var decoded map[string]any
	if err := json.Unmarshal(encoded, &decoded); err != nil {
		t.Fatal(err)
	}
	return decoded
}

func TestHealthz(t *testing.T) {
	server := httptest.NewServer(newServer())
	defer server.Close()
	body := decode[map[string]string](t, call(t, server, http.MethodGet, "/healthz", nil), http.StatusOK)
	if body["status"] != "ok" {
		t.Fatalf("status = %q", body["status"])
	}
}

