import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

var memberPayload = map[string]any{
	"name":  "example name",
	"email": "example email",
}

// makeMember creates a member and returns its id, for tests of what belongs to it.
func makeMember(t *testing.T, server *httptest.Server) float64 {
	t.Helper()
	created := decode[map[string]any](t, call(t, server, http.MethodPost, "/members", memberPayload), http.StatusCreated)
	return created["id"].(float64)
}

func TestMemberCreateAndGet(t *testing.T) {
	server := httptest.NewServer(newServer())
	defer server.Close()
	created := decode[map[string]any](t, call(t, server, http.MethodPost, "/members", memberPayload), http.StatusCreated)
	for key, want := range normalize(t, memberPayload) {
		if created[key] != want {
			t.Errorf("%s = %v, want %v", key, created[key], want)
		}
	}
	fetched := decode[map[string]any](t, call(t, server, http.MethodGet, fmt.Sprintf("/members/%v", created["id"]), nil), http.StatusOK)
	if fetched["id"] != created["id"] {
		t.Fatalf("id = %v, want %v", fetched["id"], created["id"])
	}
}

func TestMemberListPaginates(t *testing.T) {
	server := httptest.NewServer(newServer())
	defer server.Close()
	for range 3 {
		expect(t, call(t, server, http.MethodPost, "/members", memberPayload), http.StatusCreated)
	}
	page := decode[[]map[string]any](t, call(t, server, http.MethodGet, "/members?limit=2&offset=1", nil), http.StatusOK)
	if len(page) != 2 {
		t.Fatalf("page has %d items, want 2", len(page))
	}
	expect(t, call(t, server, http.MethodGet, "/members?limit=0", nil), http.StatusUnprocessableEntity)
}

func TestMemberUpdate(t *testing.T) {
	server := httptest.NewServer(newServer())
	defer server.Close()
	created := decode[map[string]any](t, call(t, server, http.MethodPost, "/members", memberPayload), http.StatusCreated)
	path := fmt.Sprintf("/members/%v", created["id"])
	updated := decode[map[string]any](t, call(t, server, http.MethodPatch, path, map[string]any{"name": "updated name"}), http.StatusOK)
	if updated["name"] != "updated name" {
		t.Fatalf("name = %v", updated["name"])
	}
}

func TestMemberDelete(t *testing.T) {
	server := httptest.NewServer(newServer())
	defer server.Close()
	created := decode[map[string]any](t, call(t, server, http.MethodPost, "/members", memberPayload), http.StatusCreated)
	path := fmt.Sprintf("/members/%v", created["id"])
	expect(t, call(t, server, http.MethodDelete, path, nil), http.StatusNoContent)
	expect(t, call(t, server, http.MethodGet, path, nil), http.StatusNotFound)
}

func TestMemberUnknownIDIs404(t *testing.T) {
	server := httptest.NewServer(newServer())
	defer server.Close()
	expect(t, call(t, server, http.MethodGet, "/members/999999", nil), http.StatusNotFound)
	expect(t, call(t, server, http.MethodGet, "/members/not-a-number", nil), http.StatusNotFound)
}

func TestMemberRejectsInvalidInput(t *testing.T) {
	server := httptest.NewServer(newServer())
	defer server.Close()
	expect(t, call(t, server, http.MethodPost, "/members", map[string]any{"unknown_field": 1}), http.StatusUnprocessableEntity)
	expect(t, call(t, server, http.MethodPost, "/members", map[string]any{}), http.StatusUnprocessableEntity)
}

